import{_ as o,a0 as a,w as r,s as d,ao as n,I as p,a1 as s,A as i,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"一個通過 IRC 管理所有聊天的開源聊天工具 | LCTT x X-CMD","titleTemplate":false,"description":"一個通過 IRC 管理所有聊天的開源聊天工具 | LCTT (202002) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一個通過 IRC 管理所有聊天的開源聊天工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一個通過 IRC 管理所有聊天的開源聊天工具 | LCTT (202002) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202002/20200119 One open source chat tool to rule them all","title":"一個通過 IRC 管理所有聊天的開源聊天工具","tag":"202002","desc":""},"relativePath":"202002/20200119 One open source chat tool to rule them all.md","filePath":"[post].md"}'),u={name:"202002/20200119 One open source chat tool to rule them all.md"};function g(k,t,b,m,f,h){const l=a("Link");return r(),d("div",null,[t[35]||(t[35]=n('<h1 id="一個通過-irc-管理所有聊天的開源聊天工具" tabindex="-1">一個通過 IRC 管理所有聊天的開源聊天工具 <a class="header-anchor" href="#一個通過-irc-管理所有聊天的開源聊天工具" aria-label="Permalink to “一個通過 IRC 管理所有聊天的開源聊天工具”">​</a></h1><blockquote><p>BitlBee 將多個聊天應用集合到一個界面中。在我們的 20 個使用開源提升生產力的系列的第九篇文章中瞭解如何設置和使用 BitlBee。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202002/05/123636dw8uw34mbkqzmw84.jpg" alt=""></p><p>去年，我在 19 天裏給你介紹了 19 個新（對你而言）的生產力工具。今年，我換了一種方式：使用你在使用或者還沒使用的工具，構建一個使你可以在新一年更加高效的環境。</p><h3 id="將所有聊天都放到-bitlbee-中" tabindex="-1">將所有聊天都放到 BitlBee 中 <a class="header-anchor" href="#將所有聊天都放到-bitlbee-中" aria-label="Permalink to “將所有聊天都放到 BitlBee 中”">​</a></h3><p>即時消息和聊天已經成為網絡世界的主要內容。如果你像我一樣，你可能打開五六個不同的應用與你的朋友、同事和其他人交談。關注所有聊天真的很痛苦。謝天謝地，你可以使用一個應用（好吧，是兩個）將這些聊天整個到一個地方。</p><p><img src="https://opensource.com/sites/default/files/uploads/productivity_9-1.png" alt="BitlBee on XChat" title="BitlBee on XChat"></p>',7)),p("p",null,[s(l,{href:"https://www.bitlbee.org/"},{default:i(()=>[...t[0]||(t[0]=[e("BitlBee",-1)])]),_:1}),t[1]||(t[1]=e(" 是作為服務運行的應用，它可以將標準的 IRC 客户端與大量的消息服務進行橋接。而且，由於它本質上是 IRC 服務器，因此你可以選擇很多客户端。",-1))]),t[36]||(t[36]=n('<p>BitlBee 幾乎包含在所有 Linux 發行版中。在 Ubuntu 上安裝（我選擇的 Linux 桌面），類似這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install bitlbee-libpurple</span></span></code></pre></div><p>在其他發行版上，包名可能略有不同，但搜索 “bitlbee” 應該就能看到。</p>',3)),p("p",null,[t[4]||(t[4]=e("你會注意到我用的 libpurple 版的 BitlBee。這個版本能讓我使用 ",-1)),s(l,{href:"https://developer.pidgin.im/wiki/WhatIsLibpurple"},{default:i(()=>[...t[2]||(t[2]=[e("libpurple",-1)])]),_:1}),t[5]||(t[5]=e(" 即時消息庫中提供的所有協議，該庫最初是為 ",-1)),s(l,{href:"http://pidgin.im/"},{default:i(()=>[...t[3]||(t[3]=[e("Pidgin",-1)])]),_:1}),t[6]||(t[6]=e(" 開發的。",-1))]),p("p",null,[t[8]||(t[8]=e("安裝完成後，服務應會自動啓動。現在，使用一個 IRC 客户端（圖片中為 ",-1)),s(l,{href:"http://xchat.org/"},{default:i(()=>[...t[7]||(t[7]=[e("XChat",-1)])]),_:1}),t[9]||(t[9]=e("），我可以連接到端口 6667（標準 IRC 端口）上的服務。",-1))]),t[37]||(t[37]=n('<p><img src="https://opensource.com/sites/default/files/uploads/productivity_9-2.png" alt="Initial BitlBee connection" title="Initial BitlBee connection"></p><p>你將自動連接到控制頻道 &amp;bitlbee。此頻道對於你是獨一無二的，在多用户系統上每個人都有一個自己的。在這裏你可以配置該服務。</p><p>在控制頻道中輸入 <code>help</code>，你可以隨時獲得完整的文檔。瀏覽它，然後使用 <code>register</code> 命令在服務器上註冊帳户。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>register &lt;mypassword&gt;</span></span></code></pre></div><p>現在，你在服務器上所做的任何配置更改（IM 帳户、設置等）都將在輸入 <code>save</code> 時保存。每當你連接時，使用 <code>identify &lt;mypassword&gt;</code> 連接到你的帳户並加載這些設置。</p><p><img src="https://opensource.com/sites/default/files/uploads/productivity_9-3.png" alt="purple settings" title="purple settings"></p>',6)),p("p",null,[t[11]||(t[11]=e("命令 ",-1)),t[12]||(t[12]=p("code",null,"help purple",-1)),t[13]||(t[13]=e(" 將顯示 libpurple 提供的所有可用協議。例如，我安裝了 ",-1)),s(l,{href:"https://github.com/majn/telegram-purple"},{default:i(()=>[...t[10]||(t[10]=[e("telegram-purple",-1)])]),_:1}),t[14]||(t[14]=e(" 包，它增加了連接到 Telegram 的能力。我可以使用 ",-1)),t[15]||(t[15]=p("code",null,"account add",-1)),t[16]||(t[16]=e(" 命令將我的電話號碼作為帳户添加。",-1))]),t[38]||(t[38]=n('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>account add telegram +15555555</span></span></code></pre></div><p>BitlBee 將顯示它已添加帳户。你可以使用 <code>account list</code> 列出你的帳户。因為我只有一個帳户，我可以通過 <code>account 0 on</code> 登錄，它會進行 Telegram 登錄，列出我所有的朋友和聊天，接下來就能正常聊天了。</p>',2)),p("p",null,[t[18]||(t[18]=e("但是，對於 Slack 這個最常見的聊天系統之一呢？你可以安裝 ",-1)),s(l,{href:"https://github.com/dylex/slack-libpurple"},{default:i(()=>[...t[17]||(t[17]=[e("slack-libpurple",-1)])]),_:1}),t[19]||(t[19]=e(" 插件，並且對 Slack 執行同樣的操作。如果你不願意編譯和安裝這些，這可能不適合你。",-1))]),t[39]||(t[39]=n(`<p>按照插件頁面上的説明操作，安裝後重新啓動 BitlBee 服務。現在，當你運行 <code>help purple</code> 時，應該會列出 Slack。像其他協議一樣添加一個 Slack 帳户。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>account add slack ksonney@myslack.slack.com</span></span>
<span class="line"><span>account 1 set password my_legcay_API_token</span></span>
<span class="line"><span>account 1 on</span></span></code></pre></div><p>你知道麼，你已經連接到 Slack 中，你可以通過 <code>chat add</code> 命令添加你感興趣的 Slack 頻道。比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>chat add 1 happyparty</span></span></code></pre></div><p>將 Slack 頻道 happyparty 添加為本地頻道 #happyparty。現在可以使用標準 IRC <code>/join</code> 命令訪問該頻道。這很酷。</p><p>BitlBee 和 IRC 客户端幫助我的（大部分）聊天和即時消息保存在一個地方，並減少了我的分心，因為我不再需要查找並切換到任何一個剛剛找我的應用上。</p><hr>`,7)),p("p",null,[t[21]||(t[21]=e("via: ",-1)),s(l,{href:"https://opensource.com/article/20/1/open-source-chat-tool"},{default:i(()=>[...t[20]||(t[20]=[e("https://opensource.com/article/20/1/open-source-chat-tool",-1)])]),_:1})]),p("p",null,[t[26]||(t[26]=e("作者：",-1)),s(l,{href:"https://opensource.com/users/ksonney"},{default:i(()=>[...t[22]||(t[22]=[e("Kevin Sonney",-1)])]),_:1}),t[27]||(t[27]=e(" 選題：",-1)),s(l,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[23]||(t[23]=[e("lujun9972",-1)])]),_:1}),t[28]||(t[28]=e(" 譯者：",-1)),s(l,{href:"https://github.com/geekpi"},{default:i(()=>[...t[24]||(t[24]=[e("geekpi",-1)])]),_:1}),t[29]||(t[29]=e(" 校對：",-1)),s(l,{href:"https://github.com/wxy"},{default:i(()=>[...t[25]||(t[25]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[32]||(t[32]=e("本文由 ",-1)),s(l,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[30]||(t[30]=[e("LCTT",-1)])]),_:1}),t[33]||(t[33]=e(" 原創編譯，",-1)),s(l,{href:"https://linux.cn/"},{default:i(()=>[...t[31]||(t[31]=[e("Linux中國",-1)])]),_:1}),t[34]||(t[34]=e(" 榮譽推出",-1))])])}const B=o(u,[["render",g]]);export{y as __pageData,B as default};
